// Package data embeds the tables generated by cmd/datagen. Regenerate with
// `make data`; see data/LICENSES.md for sources and licences.
package data

import (
	"embed"
	"io/fs"
	"strings"
)

// Segments: PHOIBLE segments with feature bits and frequency.
//
//go:embed segments.tsv
var Segments string

// Diacritics: diacritic feature deltas derived from PHOIBLE.
//
//go:embed diacritics.tsv
var Diacritics string

// NFC: precomposed characters and their decompositions.
//
//go:embed nfc.tsv
var NFC string

// Concepts: concept list with Concepticon IDs, fields and curated metadata.
//
//go:embed concepts.tsv
var Concepts string

// Colex: CLICS³ colexification edges between our concepts.
//
//go:embed colex.tsv
var Colex string

// WALS: word-order value counts and joint counts.
//
//go:embed wals.tsv
var WALS string

// Romance: IE-CoR forms of five Romance languages, for calibration tests.
//
//go:embed romance.tsv
var Romance string

//go:embed protos/*.tsv
var protoFS embed.FS

// Protos returns the real proto-language tables (protos/<id>.tsv), keyed
// by ID. They are hand-written, not generated; see each file's header.
func Protos() map[string]string {
	out := map[string]string{}
	ents, _ := fs.ReadDir(protoFS, "protos")
	for _, e := range ents {
		b, err := protoFS.ReadFile("protos/" + e.Name())
		if err == nil {
			out[strings.TrimSuffix(e.Name(), ".tsv")] = string(b)
		}
	}
	return out
}

// Lines splits an embedded TSV table into fields, skipping blank lines and
// '#' comments.
func Lines(s string) [][]string {
	var out [][]string
	start := 0
	for i := 0; i <= len(s); i++ {
		if i < len(s) && s[i] != '\n' {
			continue
		}
		line := s[start:i]
		start = i + 1
		if line == "" || line[0] == '#' {
			continue
		}
		var fields []string
		f := 0
		for j := 0; j <= len(line); j++ {
			if j == len(line) || line[j] == '\t' {
				fields = append(fields, line[f:j])
				f = j + 1
			}
		}
		out = append(out, fields)
	}
	return out
}
